// Loads data/library.json (generated by `figurelib.py site`) and keeps small client state.
import { storage } from "./util.js";

const listeners = new Map();
export function on(event, fn) {
  if (!listeners.has(event)) listeners.set(event, new Set());
  listeners.get(event).add(fn);
  return () => listeners.get(event).delete(fn);
}
export function emit(event, payload) {
  for (const fn of listeners.get(event) || []) fn(payload);
}

export async function loadLibrary(url = "data/library.json") {
  const response = await fetch(url, { cache: "no-cache" });
  if (!response.ok) throw new Error(`无法读取 ${url}（HTTP ${response.status}）`);
  const library = await response.json();
  if (library.api_version !== 1) throw new Error(`不支持的数据版本 ${library.api_version}`);
  const byId = new Map(library.entries.map((e) => [e.id, e]));
  return { ...library, byId };
}

// Compose tray: an ordered list of figure IDs kept in this browser.
export const tray = {
  ids() { return storage.get("tray", []); },
  has(id) { return this.ids().includes(id); },
  set(ids) { storage.set("tray", [...new Set(ids)]); emit("tray", this.ids()); },
  add(id) { if (!this.has(id)) this.set([...this.ids(), id]); },
  remove(id) { this.set(this.ids().filter((x) => x !== id)); },
  toggle(id) { this.has(id) ? this.remove(id) : this.add(id); return this.has(id); },
};
